class MinHeap {
  private a: ListNode[] = [];
  get size(): number { return this.a.length; }
  push(n: ListNode): void {
    const a = this.a;
    a.push(n);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p].val <= a[i].val) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): ListNode {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l].val < a[m].val) m = l;
        if (r < a.length && a[r].val < a[m].val) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function mergeMany(lists: (ListNode | null)[]): ListNode | null {
  const heap = new MinHeap();
  for (const l of lists) if (l) heap.push(l);
  const dummy = new ListNode(0);
  let tail = dummy;
  while (heap.size) {
    const n = heap.pop();
    tail.next = n;
    tail = n;
    if (n.next) heap.push(n.next);
  }
  tail.next = null;
  return dummy.next;
}

