      else { tail.next = b; b = b.next; }
      tail = tail.next;
    }
    tail.next = a ?? b;
    return dummy.next;
  };
  if (!lists.length) return null;
  let cur = lists;
  while (cur.length > 1) {
    const next: (ListNode | null)[] = [];
    for (let i = 0; i < cur.length; i += 2) next.push(mergeTwo(cur[i], i + 1 < cur.length ? cur[i + 1] : null));
    cur = next;
  }
  return cur[0];
}

